export function getVehicleLiveryIcon(vehicleId, id) { return liveries[`${vehicleId}/${id}`] ?? null; }
export function getVehicleNeonIcon(id) { return neon[id] ?? null; }
export function getVehicleSmokeIcon(id) { return smoke[id] ?? null; }
export function getVehicleCosmeticCategoryIcon(section) { return categories[section] ?? null; }
